function t3MaterialCss() {
  const rules = [];
  const block = (values) => T3_MAT_KEYS.map((key, i) => `--anatomy-${key}:${values[i]}`).concat(T3_MAT_TUBE.map((key, i) => `--mat-${key}:${values[T3_MAT_KEYS.length + i]}`)).join(";");
  for (const [name, { light, dark }] of Object.entries(T3_MATERIALS)) {
    rules.push(`[data-mat="${name}"]{${block(dark)}}`);
    rules.push(`.iso[data-theme="light"] [data-mat="${name}"]{${block(light)}}`);
    rules.push(`.iso[data-theme="dark"] [data-mat="${name}"]{${block(dark)}}`);
  }
  rules.push("[data-mat] .tb-body{fill:var(--mat-body)}");
  rules.push("[data-mat] .tb-shine{fill:var(--mat-shine)}");
  rules.push("[data-mat] .tb-shade{fill:var(--mat-shade)}");
  rules.push("[data-mat] .tb-edge{stroke:var(--mat-edge)}");
  return rules.join("\n");
}

function t3Css() {
  const rules = [];
  const ramp = "--tn-0:var(--anatomy-shade-0);--tn-1:var(--anatomy-shade-1);--tn-2:var(--anatomy-shade-2);--tn-3:var(--anatomy-shade-3);--tn-4:var(--anatomy-top)";
  rules.push(`.iso-live{${ramp}}`);
  rules.push(`.iso-live [data-mat]{${ramp}}`);
  rules.push(".iso-live [data-lit]{--tn-0:var(--anatomy-lit-shade);--tn-1:var(--anatomy-lit-shade);--tn-2:var(--anatomy-lit-shade);--tn-3:var(--anatomy-lit-shade);--tn-4:var(--anatomy-lit-top)}");
  const colour = "color-mix(in srgb,var(--ta) calc(100% - var(--f,0) * 100%),var(--tb))";
  rules.push(`.iso-tn{stroke-width:.4;stroke-linejoin:round;--ta:var(--tn-0);--tb:var(--tn-1);fill:${colour};stroke:${colour}}`);
  for (let i = 1; i < 4; i++) rules.push(`.iso-tn[data-b="${i}"]{--ta:var(--tn-${i});--tb:var(--tn-${i + 1})}`);
  rules.push(t3MaterialCss());
  for (const hue of ["red", "green", "blue"]) rules.push(`.tb[data-hue="${hue}"]{--tb-ink:var(--anatomy-${hue})}`);
  rules.push(".tb[data-hue] .tb-body{fill:color-mix(in srgb,var(--tb-ink) 54%,var(--anatomy-shade-2))}");
  rules.push(".tb[data-hue] .tb-shine{fill:color-mix(in srgb,var(--tb-ink) 16%,var(--anatomy-top))}");
  rules.push(".tb[data-hue] .tb-shade{fill:color-mix(in srgb,var(--tb-ink) 30%,var(--anatomy-hi))}");
  rules.push(".tb[data-hue] .tb-edge{stroke:color-mix(in srgb,var(--tb-ink) 38%,var(--anatomy-hi))}");
  rules.push(".tb[data-hue][data-mat] .tb-body{fill:color-mix(in srgb,var(--tb-ink) 62%,var(--mat-body))}");
  rules.push(".tb[data-hue][data-mat] .tb-shine{fill:color-mix(in srgb,var(--tb-ink) 22%,var(--mat-shine))}");
  rules.push(".tb[data-hue][data-mat] .tb-shade{fill:color-mix(in srgb,var(--tb-ink) 46%,var(--mat-shade))}");
  rules.push(".tb[data-hue][data-mat] .tb-edge{stroke:color-mix(in srgb,var(--tb-ink) 30%,var(--mat-edge))}");
  rules.push(".iso-turn{position:relative}");
  rules.push(".iso-turn>.iso-layer{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}");
  return rules.join("\n");
}

const TURN = { materials: Object.keys(T3_MATERIALS), materialCss: t3MaterialCss, rotation: (axis, degrees) => Array.from(t3Rot(axis, degrees)), quat: (q) => Array.from(t3Quat(q)), compose: t3Compose, floorOf: t3FloorOf, anchor: t3Anchor, camera: t3Camera, poses: t3PosesMap, prepare: t3Prepare, emit: t3Emit, order: t3Order, mount: t3Mount, cover: t3Cover, poseUniforms: t3PoseUniforms, css: t3Css, frame: t3Frame, cams: t3Cams, gjk: t3Gjk, hintsOf: (ri, ci, rj, cj, world) => Object.assign([...ri.axes.map((axis) => [axis, ci]), ...rj.axes.map((axis) => [axis, cj]), [[0, 0, 1], world]], { centroids: [ri.centroid, rj.centroid] }), disjoint: t3Disjoint, levels: T3_LEVELS, q: T3_Q, exact: (on) => { t3State.exact = Boolean(on); } };
const TURN_CSS = t3Css();

const JS_MODEL = (() => {
// Pure motion model for the job-card sorting machine. No imports: the build inlines this file into the
// runtime and samples it for the engine's poses and the orbit audit.
//
// One loop is one job card's life:
//   the card sits on the hopper stack  ->  slides under the reading brush, which checks its three holes
//   (photos, booked site visit, form sent: three lamps light)  ->  it drops into the stage 1 pocket, lifts,
//   moves on to stage 2, stage 3, and drops into the last pocket  ->  the invoice stamp comes down and the
//   card is marked INVOICED  ->  it fades away and a fresh card sits on the hopper again.
// Beside it the test bench runs its row of lamps and the gauge swings to pass, once per loop.
// t = 0 is the rest pose (everything parked, the card on the hopper, lamps off): the runtime parks there
// before the machine comes apart.

const LOOP = 14; // seconds per card
const IDS = ["hopper", "brush", "pegboard", "stamp", "patch", "chute", "bench"];
const BRUSH_AT = 34; // card travel from the hopper to the reading brush
const POCKETS = [60.4, 75.6, 90.8, 106]; // card travel to each pocket (the last one is the stamp's)
const DIP = 8; // how far a card drops into a pocket
const HEAD = 8.3; // invoice stamp head travel
const NEEDLE = 40; // the test gauge settles here (pass side)
const NEEDLE_REST = -50;
const TRAVEL = { hopper: 30, pegboard: 26, patch: 26, stamp: 30, chute: 28, bench: 26, brush: 0 };
// [start, length] of each assembly's share of the explode progress p (0..1)
const STAGGER = { hopper: [0, 0.5], chute: [0.06, 0.5], bench: [0.12, 0.5], stamp: [0.18, 0.5], patch: [0.24, 0.5], pegboard: [0.3, 0.55], brush: [0, 1] };

const smooth = (x) => (x <= 0 ? 0 : x >= 1 ? 1 : x * x * x * (x * (6 * x - 15) + 10));
const win = (t, a, d) => smooth((t - a) / d);

function explodeValues(p) {
  const out = {};
  for (const id of Object.keys(TRAVEL)) {
    if (!TRAVEL[id]) continue;
    out[`ex.${id}`] = TRAVEL[id] * smooth((p - STAGGER[id][0]) / STAGGER[id][1]);
  }
  return out;
}

// Everything that moves during one card's journey, t in seconds (0..LOOP).
function cardState(t) {
  t = ((t % LOOP) + LOOP) % LOOP;
  // travel along the track (x) and the drop into a pocket (dip); the return trip runs while the card is hidden
  let x = BRUSH_AT * win(t, 0.8, 1.2);
  x += (POCKETS[0] - BRUSH_AT) * win(t, 3.0, 0.9);
  x += (POCKETS[1] - POCKETS[0]) * win(t, 5.3, 0.6);
  x += (POCKETS[2] - POCKETS[1]) * win(t, 7.3, 0.6);
  x += (POCKETS[3] - POCKETS[2]) * win(t, 9.3, 0.6);
  x -= POCKETS[3] * win(t, 13.3, 0.6);
  const dip =
    DIP *
    (win(t, 4.0, 0.5) * (1 - win(t, 4.8, 0.4)) +
      win(t, 6.0, 0.5) * (1 - win(t, 6.8, 0.4)) +
      win(t, 8.0, 0.5) * (1 - win(t, 8.8, 0.4)) +
      win(t, 10.0, 0.5) * (1 - win(t, 13.0, 0.3)));
  // the reading brush: one lamp per hole while the card is under it
  const holes = [0, 1, 2].map((i) => win(t, 2.1 + 0.3 * i, 0.15) * (1 - win(t, 3.1, 0.3)));
  // the invoice stamp
  const head = HEAD * win(t, 10.6, 0.3) * (1 - win(t, 11.1, 0.5));
  const ink = win(t, 10.86, 0.1) * (1 - win(t, 12.3, 0.6));
  // the card fades out in the last pocket and back in on the hopper
  const card = 1 - win(t, 12.3, 0.6) + win(t, 13.75, 0.25);
  // test bench: five lamps in turn, then the gauge swings to pass; reset before the loop ends
  const tests = [0, 1, 2, 3, 4].map((i) => win(t, 0.6 + 0.35 * i, 0.15) * (1 - win(t, 12.2, 0.5)));
  let needle = NEEDLE_REST;
  if (t > 2.4) {
    const u = t - 2.4;
    needle += (NEEDLE - NEEDLE_REST) * (1 - Math.exp(-3.2 * u) * Math.cos(5.5 * u)) * (1 - win(t, 12.4, 0.9));
  }
  const pass = win(t, 3.6, 0.3) * (1 - win(t, 12.2, 0.5));
  // the AI module's activity lamp blinks while the card is being handled (changes are logged)
  const ai = 0.5 + 0.5 * Math.cos((t * 2 * Math.PI) / 1.4);
  return { x, dip, holes, head, ink, card, tests, needle, pass, ai };
}

// Figure values -> group values. v = { spin, explode, t (seconds) }
function follow(v) {
  const out = { spin: v.spin ?? 0, ...explodeValues(v.explode ?? 0) };
  const s = cardState(v.t ?? 0);
  out["card.x"] = s.x;
  out["card.dip"] = s.dip;
  out["stamp.head"] = s.head;
  out.needle = s.needle;
  return out;
}

return { follow, cardState, explodeValues, LOOP, smooth, IDS };
})();
